const root = resolve(import.meta.dirname, '..')
const scratch = join(root, '.scratch')
mkdirSync(scratch, { recursive: true })
const consumer = mkdtempSync(join(scratch, 'v1-surface-'))
function run(command: string, args: string[], cwd = root) {
  return execFileSync(command, args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  })
}
function save(name: string, contents: string) {
  writeFileSync(join(consumer, name), contents)
}
try {
  run('bun', ['run', 'build'])
  const [pack] = JSON.parse(
    run('npm', ['pack', './src', '--json', '--pack-destination', consumer]),
  )
  const viem = JSON.parse(
    readFileSync(join(root, 'node_modules/viem/package.json'), 'utf8'),
  ).version
  save(
    'package.json',
    JSON.stringify({
      private: true,
      dependencies: {
        '@rhinestone/sdk': `file:./${pack.filename}`,
        viem,
        jose: '^6.2.2',
        express: '^4.21.2',
      },
    }),
  )
  // npm must install the tarball, not link the workspace or inherit its aliases.
  run(
    'npm',
    ['install', '--ignore-scripts', '--no-audit', '--no-fund'],
    consumer,
  )
  const installed = join(consumer, 'node_modules/@rhinestone/sdk')
  const manifest = JSON.parse(
    readFileSync(join(installed, 'package.json'), 'utf8'),
  )
  assert.deepEqual(
    manifest.exports,
    Object.fromEntries(
      Object.entries(baseline).map(
        ([key, { names: _names, values: _values, ...entry }]) => [key, entry],
      ),
    ),
    'Export map changed',
  )

  const entries = Object.values(baseline).map((entry) =>
    join(installed, entry.types),
  )
  const program = ts.createProgram(entries, {
    skipLibCheck: true,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
  })
  const checker = program.getTypeChecker()
  for (const [subpath, entry] of Object.entries(baseline)) {
    const file = program.getSourceFile(join(installed, entry.types))
    assert(file, `Missing declarations: ${subpath}`)
    const symbol = checker.getSymbolAtLocation(file)
    assert(symbol, `Missing module: ${subpath}`)
    assert.deepEqual(
      checker
        .getExportsOfModule(symbol)
        .map((symbol) => symbol.name)
        .sort(),
      entry.names.split(' '),
      `Named exports changed: ${subpath}`,
    )
  }

  const deprecated: Record<string, string[]> = {
    'orchestrator/client': ['getIntentRoute', 'submitIntent'],
    'orchestrator/types': [
      'IntentRoute',
      'IntentOp',
      'SignedIntentOp',
      'IntentOpElement',
      'IntentOpElementMandate',
      'IntentCost',
      'IntentResult',
      'FeeBreakdown',
      'FeeBreakdownUSD',
      'FeesByTokenEntry',
      'Op',
      'ExecutionWithPlaceholders',
      'ElementSwapDestination',
      'ElementSwapOrigin',
    ],
    'execution/compact': [
      'getCompactTypedData',
      'getCompactDigest',
      'getPermit2Digest',
    ],
    'execution/singleChainOps': ['getTypedData'],
    'execution/permit2': [
      'getTypedData',
      'signPermit2Batch',
      'signPermit2Sequential',
    ],
    'execution/types': [
      'MultiChainPermit2Config',
      'MultiChainPermit2Result',
      'BatchPermit2Result',
    ],
    types: ['feeAsset', 'lockFunds'],
  }
  for (const [path, names] of Object.entries(deprecated)) {
    const file = program.getSourceFile(join(installed, `dist/src/${path}.d.ts`))
    assert(file, `Missing declaration file: ${path}`)
    const found = new Set<string>()
    function visit(node: ts.Node) {
      const name = (node as ts.NamedDeclaration).name
      if (name && ts.isIdentifier(name) && names.includes(name.text)) {
        if (ts.getJSDocDeprecatedTag(node)) found.add(name.text)
      }
      ts.forEachChild(node, visit)
    }
    visit(file)
    assert.deepEqual(
      [...found].sort(),
      [...names].sort(),
      `Missing @deprecated in ${path}`,
    )
  }

  const readme = readFileSync(join(installed, 'README.md'), 'utf8')
  assert.equal(
    readme,
    readFileSync(join(root, 'src/README.md'), 'utf8'),
    'Packed README differs',
  )
  for (const text of [
    '@rhinestone/sdk@v1-latest',
    '1.23.0',
    'intentRoute',
    'quote.cost',
    "apiVersion: 'blanc'",
    'computeBlancIntentInputDigest',
    'Re-prepare and re-sign',
  ])
    assert(readme.includes(text), `Missing migration guidance: ${text}`)

  cpSync(join(root, 'test/types/v1-blanc.ts'), join(consumer, 'fixture.mts'))
  // Every named export (including type-only exports) must resolve through the package map.
  save(
    'exports.mts',
    Object.entries(baseline)
      .map(
        ([path, entry], index) =>
          `import type { ${entry.names
            .split(' ')
            .map((name) => `${name} as E${index}_${name}`)
            .join(
              ', ',
            )} } from '${path === '.' ? '@rhinestone/sdk' : `@rhinestone/sdk/${path.slice(2)}`}'`,
      )
      .join('\n'),
  )
  const prelude = `import { RhinestoneSDK } from '@rhinestone/sdk'\nimport { baseSepolia, arbitrumSepolia } from 'viem/chains'\nimport { encodeFunctionData, erc20Abi, type Account, type Address } from 'viem'\nimport type { JwtHandlerConfig } from '@rhinestone/sdk/jwt-server'\ndeclare const signer: Account\ndeclare const myJwk: JwtHandlerConfig['jwt']['privateKey']\ndeclare const jwtCredentials: JwtHandlerConfig['jwt']\ndeclare const isUser: (address: Address) => Promise<boolean>\nconst amount = 1n\nconst recipient: Address = '0x0000000000000000000000000000000000000001'\nconst account = await new RhinestoneSDK({ apiKey: 'example' }).createAccount({ owners: { type: 'ecdsa', accounts: [signer] } })\n`
  const examples = [...readme.matchAll(/```ts\n([\s\S]*?)```/g)]
  assert(examples.length > 0, 'No README examples found')
  examples.forEach(([_, code], index) => {
    // Examples share quickstart context, but have independent local bindings.
    const imports = [...code.matchAll(/import[\s\S]*?from ['"][^'"]+['"]/g)]
      .map((match) => match[0])
      .join('\n')
    const body = code.replace(/import[\s\S]*?from ['"][^'"]+['"]/g, '')
    const context = prelude
      .replace(
        'declare const signer: Account',
        code.includes('const signer =')
          ? 'declare const owner: Account'
          : 'declare const signer: Account',
      )
      .replace(
        'accounts: [signer]',
        code.includes('const signer =')
          ? 'accounts: [owner]'
          : 'accounts: [signer]',
      )
      .replace(
        /const account = .*\n/,
        code.includes('const account =') ? '' : '$&',
      )
    save(
      `readme-${index}.mts`,
      `${context}${imports.replace(/import \{ RhinestoneSDK \} from '@rhinestone\/sdk'/g, '').replace(/type JwtHandlerConfig,?/g, '')}\n${body}`,
    )
  })
  save(
    'tsconfig.json',
    JSON.stringify({
      compilerOptions: {
        strict: true,
        noEmit: true,
        skipLibCheck: true,
        target: 'ES2022',
        module: 'NodeNext',
        moduleResolution: 'NodeNext',
      },
      include: ['*.mts'],
    }),
  )
  run(
    'node',
    [
      join(root, 'node_modules/typescript/bin/tsc'),
      '-p',
      join(consumer, 'tsconfig.json'),
    ],
    consumer,
  )
  const runtime = JSON.stringify(
    Object.entries(baseline).map(([path, entry]) => [
      path === '.' ? '@rhinestone/sdk' : `@rhinestone/sdk/${path.slice(2)}`,
      entry.values ? entry.values.split(' ') : [],
    ]),
  )
  save(
    'runtime.cjs',
    `const assert = require('node:assert/strict'); for (const [path, names] of ${runtime}) { const mod = require(path); assert.deepEqual(Object.keys(mod).filter(k => k !== '__esModule').sort(), names, path); }`,
  )
  save(
    'runtime.mjs',
    `import assert from 'node:assert/strict'; for (const [path, names] of ${runtime}) { const mod = await import(path); for (const name of names) assert.ok(name in mod, path + ': ' + name); }`,
  )
  run('node', ['runtime.cjs'], consumer)
  run('node', ['runtime.mjs'], consumer)
  process.stdout.write(
    `v1 packed surface passed: ${Object.keys(baseline).length} entry points, ${examples.length} README examples\n`,
  )
} finally {
  rmSync(consumer, { recursive: true, force: true })
}
